23	const (
24		maxTranscriptionAudioSizeBytes = 25 * MebiByte
25		maxTranscriptionFilenameLength = 255
26	)
27	
28	var supportedTranscriptionContentTypes = map[string]bool{
29		"audio/aac":    true,
30		"audio/aiff":   true,
31		"audio/flac":   true,
32		"audio/mpeg":   true,
33		"audio/mp3":    true,
34		"audio/mp4":    true,
35		"audio/mpga":   true,
36		"audio/ogg":    true,
37		"audio/wav":    true,
38		"audio/x-wav":  true,
39		"audio/x-flac": true,
40		"audio/x-m4a":  true,
41		"audio/webm":   true,
42		"video/mp4":    true,
43		"video/mpeg":   true,
