317		user, err := s.fetchCurrentUser(ctx)
318		if err != nil {
319			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
320		}
321		if user == nil {
322			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
323		}
324		attachment, err := s.Store.GetAttachment(ctx, &store.FindAttachment{
325			UID:       &attachmentUID,
326			CreatorID: &user.ID,
327		})
328		if err != nil {
329			return nil, status.Errorf(codes.Internal, "failed to find attachment: %v", err)
330		}
331		if attachment == nil {
332			return nil, status.Errorf(codes.NotFound, "attachment not found")
333		}
334		// Delete the attachment from the database.
335		if err := s.Store.DeleteAttachment(ctx, &store.DeleteAttachment{
336			ID: attachment.ID,
337		}); err != nil {
338			return nil, status.Errorf(codes.Internal, "failed to delete attachment: %v", err)
